(6835418, 1026724, 35086, '<td valign="top">Love the shades of blue here and so crisp.  I really like this.</td>', 'Love the shades of blue here and so crisp.  I really like this.', '2012-08-05 15:59:57.000000', NULL, 1),
(6835419, 1028317, 35086, '<td valign="top">That''s actually kinda scary.. the eyes!</td>', 'That''s actually kinda scary.. the eyes!', '2012-08-05 16:00:26.000000', NULL, 1),
(6835420, 1028347, 35086, '<td valign="top">It''s really nice but I would have used a different composition and perhaps a bit more contrast.</td>', 'It''s really nice but I would have used a different composition and perhaps a bit more contrast.', '2012-08-05 16:02:14.000000', NULL, 1),
(6835421, 1027561, 35086, '<td valign="top">Simple and yet so strong.  I like this a lot.</td>', 'Simple and yet so strong.  I like this a lot.', '2012-08-05 16:02:54.000000', NULL, 1),
(6835423, 1026290, 35086, '<td valign="top">Is that how they let their dishes dry over there?  I like the tones in this one. :)</td>', 'Is that how they let their dishes dry over there?  I like the tones in this one. :)', '2012-08-05 16:03:39.000000', NULL, 1),
(6835424, 1025681, 35086, '<td valign="top">I like the strong features which you''ve captured so well here.  Good stuff.</td>', 'I like the strong features which you''ve captured so well here.  Good stuff.', '2012-08-05 16:06:02.000000', NULL, 1),
(6835426, 1027614, 35086, '<td valign="top">Great concept and excellent execution.  Wins a high score from me for sure.</td>', 'Great concept and excellent execution.  Wins a high score from me for sure.', '2012-08-05 16:06:42.000000', NULL, 1),
(6835427, 1025402, 103032, '<td valign="top">I like the dichotomy of this shot.  The processing and semi-sepia treatment makes this a vintage feeling type shot, but the new technology of the modern windmills adds an interesting element.  Also the motion of the windmill blades adds to the interest.</td>', 'I like the dichotomy of this shot.  The processing and semi-sepia treatment makes this a vintage feeling type shot, but the new technology of the modern windmills adds an interesting element.  Also the motion of the windmill blades adds to the interest.', '2012-08-05 16:06:49.000000', NULL, 1),
(6835429, 1027446, 103032, '<td valign="top">Looks like chaos in the underworld.  The "highlighted" part in the bottom portion may be the way of escape.  Interesting abstract to look at.  Have to guess pixelpig, having seen her forks in the July Blur SC.</td>', 'Looks like chaos in the underworld.  The "highlighted" part in the bottom portion may be the way of escape.  Interesting abstract to look at.  Have to guess pixelpig, having seen her forks in the July Blur SC.', '2012-08-05 16:12:44.000000', NULL, 1),
(6835431, 1027493, 103032, '<td valign="top">Double rainbows, nice.  You don''t see those everyday.  Nice capture.  Like how the lower corners are darkened.  Don''t know if that was done in post, but adds to the "This is the way" feeling under the rainbow.  Very cheerful image.</td>', 'Double rainbows, nice.  You don''t see those everyday.  Nice capture.  Like how the lower corners are darkened.  Don''t know if that was done in post, but adds to the "This is the way" feeling under the rainbow.  Very cheerful image.', '2012-08-05 16:15:46.000000', NULL, 1),
(6835434, 1027535, 103032, '<td valign="top">Kind of Edgar Allan Poe-ish feel.</td>', 'Kind of Edgar Allan Poe-ish feel.', '2012-08-05 16:19:40.000000', NULL, 1),
(6835436, 1027962, 103032, '<td valign="top">Like the elements here.  Cool cloudy sky with sun rays. Like the silhouettes of the trees and truck and car.  I''m usually not influenced by titles, but your title is fitting.  If only there was an isolated farmhouse.  This is one that takes a bit of a longer look and the message/story to appreciate IMHO.  I think it should end up &gt;6 in the scoring.  Best of luck.</td>', 'Like the elements here.  Cool cloudy sky with sun rays. Like the silhouettes of the trees and truck and car.  I''m usually not influenced by titles, but your title is fitting.  If only there was an isolated farmhouse.  This is one that takes a bit of a longer look and the message/story to appreciate IMHO.  I think it should end up >6 in the scoring.  Best of luck.', '2012-08-05 16:25:43.000000', NULL, 1),
(6835438, 1027514, 103032, '<td valign="top">Nice portrait. Like the "softness" (don''t know if that''s the right term) of the processing.  He just looks a little stiff.</td>', 'Nice portrait. Like the "softness" (don''t know if that''s the right term) of the processing.  He just looks a little stiff.', '2012-08-05 16:30:33.000000', NULL, 1),
(6835460, 1027946, 65234, '<td valign="top">Phenomenal capture!  Love the light and the timing is incredible.  That feather was a gift :-)</td>', 'Phenomenal capture!  Love the light and the timing is incredible.  That feather was a gift :-)', '2012-08-05 17:04:07.000000', NULL, 1),
(6835461, 1026760, 65234, '<td valign="top">Love the perspective, the crispness of the grass, the blue of the sky, and oh, those magnificent, stately elephants.  Wonderful :-)))</td>', 'Love the perspective, the crispness of the grass, the blue of the sky, and oh, those magnificent, stately elephants.  Wonderful :-)))', '2012-08-05 17:06:40.000000', NULL, 1),
(6835468, 1027175, 65234, '<td valign="top">A whole field of gorgeous blue flowers in golden light; heaven!</td>', 'A whole field of gorgeous blue flowers in golden light; heaven!', '2012-08-05 17:11:44.000000', NULL, 1),
(6835473, 1027803, 65234, '<td valign="top">Like the light and softness but I''m not sure about the crop.  I think I''d like it better much tighter on the hands and what I assume is a Bible, and maybe from a slightly lower angle.</td>', 'Like the light and softness but I''m not sure about the crop.  I think I''d like it better much tighter on the hands and what I assume is a Bible, and maybe from a slightly lower angle.', '2012-08-05 17:26:06.000000', NULL, 1),
(6835496, 1028253, 65234, '<td valign="top">Love the composition and colors.  That mantis is sitting pretty!</td>', 'Love the composition and colors.  That mantis is sitting pretty!', '2012-08-05 17:51:51.000000', NULL, 1),
(6835497, 1027393, 65234, '<td valign="top">Like the composition and colors.  Would like a bit sharper focus on the eye.</td>', 'Like the composition and colors.  Would like a bit sharper focus on the eye.', '2012-08-05 17:53:43.000000', NULL, 1),
(6835500, 1027535, 65234, '<td valign="top">Love the composition and color!  Great sky.  The smooth arc of the light pole is almost jarring against all those random, intricate cloud patterns, but it leads my eye straight to the hawk and the moon above him.  Just a very cool scene.</td>', 'Love the composition and color!  Great sky.  The smooth arc of the light pole is almost jarring against all those random, intricate cloud patterns, but it leads my eye straight to the hawk and the moon above him.  Just a very cool scene.', '2012-08-05 18:01:18.000000', NULL, 1),
(6835501, 1027110, 65234, '<td valign="top">I think the poor little grasshopper is feeling overwhelmed by that bulbous top he''s facing.  Lovely golden/green colors.  A bit of sensor dust, it looks like, which I''d clone out.</td>', 'I think the poor little grasshopper is feeling overwhelmed by that bulbous top he''s facing.  Lovely golden/green colors.  A bit of sensor dust, it looks like, which I''d clone out.', '2012-08-05 18:03:20.000000', NULL, 1),
(6835502, 1028321, 65234, '<td valign="top">Sooner or later every Osprey needs to fly and catch his own fish, dude. You can do it, too!</td>', 'Sooner or later every Osprey needs to fly and catch his own fish, dude. You can do it, too!', '2012-08-05 18:05:00.000000', NULL, 1),
(6835503, 1028197, 65234, '<td valign="top">Gorgeous color and really interesting formations.</td>', 'Gorgeous color and really interesting formations.', '2012-08-05 18:12:26.000000', NULL, 1),
(6835504, 1028289, 65234, '<td valign="top">Love the light and delicacy.</td>', 'Love the light and delicacy.', '2012-08-05 18:13:40.000000', NULL, 1),
(6835505, 1028317, 65234, '<td valign="top">Dang, they''re cute!!!</td>', 'Dang, they''re cute!!!', '2012-08-05 18:19:21.000000', NULL, 1),
(6835506, 1025092, 65234, '<td valign="top">Wow; fascinating place!</td>', 'Wow; fascinating place!', '2012-08-05 18:20:08.000000', NULL, 1),
(6835507, 1027406, 65234, '<td valign="top">Love Morning Glories!  Mine seem to be casualties of our hot, dry summer :-(. Like the light through the blossom.</td>', 'Love Morning Glories!  Mine seem to be casualties of our hot, dry summer :-(. Like the light through the blossom.', '2012-08-05 18:22:13.000000', NULL, 1),
(6835508, 1026458, 65234, '<td valign="top">Love the color contrast; everything is peacefully muted except for that chair.  Bet I''d hate it if I was a neighbor with a view of it LOL.</td>', 'Love the color contrast; everything is peacefully muted except for that chair.  Bet I''d hate it if I was a neighbor with a view of it LOL.', '2012-08-05 18:24:42.000000', NULL, 1),
(6835509, 1027396, 65234, '<td valign="top">The sun is literally bursting onto the scene.  Almost pretty enough to make me like mornings better ;-)</td>', 'The sun is literally bursting onto the scene.  Almost pretty enough to make me like mornings better ;-)', '2012-08-05 18:25:35.000000', NULL, 1),
(6835510, 1026435, 65234, '<td valign="top">Someone''s been snacking on the crops!</td>', 'Someone''s been snacking on the crops!', '2012-08-05 18:26:26.000000', NULL, 1),
(6835511, 1027996, 65234, '<td valign="top">Is that a clematis?  They do look very interesting after the flowers fade.</td>', 'Is that a clematis?  They do look very interesting after the flowers fade.', '2012-08-05 18:27:54.000000', NULL, 1),
(6835517, 1028287, 65234, '<td valign="top">Yikes!!!  That may just be discoloration but it looks like blood on his fangs, and his expression says he''d happily sink them into a new victim =:-0</td>', 'Yikes!!!  That may just be discoloration but it looks like blood on his fangs, and his expression says he''d happily sink them into a new victim =:-0', '2012-08-05 18:44:55.000000', NULL, 1),
(6835518, 1027976, 65234, '<td valign="top">I think this is a statue, and it''s rare that I''m impressed by a photo of a statue, but this has emotion to it.  Something about the solitary figure, the vast water, the beautiful light, the rippling sand ... almost apocalyptic in feel.</td>', 'I think this is a statue, and it''s rare that I''m impressed by a photo of a statue, but this has emotion to it.  Something about the solitary figure, the vast water, the beautiful light, the rippling sand ... almost apocalyptic in feel.', '2012-08-05 18:45:39.000000', NULL, 1),
(6835519, 1028049, 65234, '<td valign="top">Stunningly detailed!</td>', 'Stunningly detailed!', '2012-08-05 18:46:11.000000', NULL, 1),
(6835520, 1026146, 65234, '<td valign="top">Nicely framed!</td>', 'Nicely framed!', '2012-08-05 18:47:16.000000', NULL, 1),
(6835521, 1028002, 65234, '<td valign="top">Like the perspective and tones.  And the birds :-)</td>', 'Like the perspective and tones.  And the birds :-)', '2012-08-05 18:48:11.000000', NULL, 1),
(6835522, 1027087, 65234, '<td valign="top">Lovely, sparkly bokeh :-)</td>', 'Lovely, sparkly bokeh :-)', '2012-08-05 18:48:37.000000', NULL, 1),
(6835523, 1027503, 65234, '<td valign="top">Beautifully sharp Hummer!  And a bonus bee :-)</td>', 'Beautifully sharp Hummer!  And a bonus bee :-)', '2012-08-05 18:49:07.000000', NULL, 1),
(6835524, 1026904, 65234, '<td valign="top">What a beautiful place!  Love all the detail.</td>', 'What a beautiful place!  Love all the detail.', '2012-08-05 18:51:33.000000', NULL, 1),
(6835527, 1028327, 65234, '<td valign="top">Love the transition from bright, flowery field to stormy mountaintops.  Great scene.</td>', 'Love the transition from bright, flowery field to stormy mountaintops.  Great scene.', '2012-08-05 18:53:07.000000', NULL, 1),
(6835528, 1028285, 65234, '<td valign="top">Lovely little silhouette.</td>', 'Lovely little silhouette.', '2012-08-05 18:53:30.000000', NULL, 1),
