INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6835560, 1027614, 43774, '<td valign="top">This is so cute!!!</td>', 'This is so cute!!!', '2012-08-05 19:51:05.000000', NULL, 1),
(6835563, 1027420, 43774, '<td valign="top">Great timing!</td>', 'Great timing!', '2012-08-05 19:51:27.000000', NULL, 1),
(6835565, 1027558, 43774, '<td valign="top">Wow!!!</td>', 'Wow!!!', '2012-08-05 19:52:56.000000', NULL, 1),
(6835599, 1027976, 76335, '<td valign="top">Astounding concept, statement.</td>', 'Astounding concept, statement.', '2012-08-05 20:41:12.000000', NULL, 1),
(6835600, 1027303, 76335, '<td valign="top">Beautiful field shot.</td>', 'Beautiful field shot.', '2012-08-05 20:41:56.000000', NULL, 1),
(6835602, 1027535, 76335, '<td valign="top">a beautifully arranged image. Poetic.</td>', 'a beautifully arranged image. Poetic.', '2012-08-05 20:47:01.000000', NULL, 1),
(6835603, 1026969, 76335, '<td valign="top">Wonderful how he pops out of the rocks...</td>', 'Wonderful how he pops out of the rocks...', '2012-08-05 20:49:16.000000', NULL, 1),
(6835604, 1026803, 76335, '<td valign="top">Terrific with the broken umbrella...</td>', 'Terrific with the broken umbrella...', '2012-08-05 20:50:19.000000', NULL, 1),
(6835605, 1028290, 76335, '<td valign="top">Like a movie still...</td>', 'Like a movie still...', '2012-08-05 20:50:53.000000', NULL, 1),
(6835606, 1027893, 76335, '<td valign="top">Almost dismissed this as another cute animal shot, but the colors caught my eye and dragged me back. Composition works too with foreground and background bokeh.</td>', 'Almost dismissed this as another cute animal shot, but the colors caught my eye and dragged me back. Composition works too with foreground and background bokeh.', '2012-08-05 20:53:21.000000', NULL, 1),
(6835607, 1027417, 76335, '<td valign="top">Excellent composition. The easy-on-the-eyes contrast is a must for making this hold up.</td>', 'Excellent composition. The easy-on-the-eyes contrast is a must for making this hold up.', '2012-08-05 20:54:03.000000', NULL, 1),
(6835608, 1025959, 76335, '<td valign="top">The story of a story...</td>', 'The story of a story...', '2012-08-05 20:54:30.000000', NULL, 1),
(6835609, 1026538, 76335, '<td valign="top">Cute kid. Love the bewildered look and disheveled hair.</td>', 'Cute kid. Love the bewildered look and disheveled hair.', '2012-08-05 20:55:39.000000', NULL, 1),
(6835611, 1028261, 76335, '<td valign="top">Starry, starry...</td>', 'Starry, starry...', '2012-08-05 20:56:31.000000', NULL, 1),
(6835652, 1028213, 65234, '<td valign="top">Gorgeous pose and colors.</td>', 'Gorgeous pose and colors.', '2012-08-05 22:02:21.000000', NULL, 1),
(6835676, 1027397, 10785, '<td valign="top">Solid photo with good exposure, focus and processing. I think it''s a little dark and could be brighter. It has very even lighting but I think it is not very luminous.</td>', 'Solid photo with good exposure, focus and processing. I think it''s a little dark and could be brighter. It has very even lighting but I think it is not very luminous.', '2012-08-05 22:15:42.000000', NULL, 1),
(6835684, 1027834, 10785, '<td valign="top">Good little HDR. You got a good perspective on the building, but perhaps could have changed the viewpoint to add interest. Shooting a box from near or at standing position at eye level doesn''t add much interest. Suffers from lack of shape and form but it is not your fault, just a plain subject. Could be sharper and there are some uneven tones in the sky.</td>', 'Good little HDR. You got a good perspective on the building, but perhaps could have changed the viewpoint to add interest. Shooting a box from near or at standing position at eye level doesn''t add much interest. Suffers from lack of shape and form but it is not your fault, just a plain subject. Could be sharper and there are some uneven tones in the sky.', '2012-08-05 22:20:23.000000', NULL, 1),
(6835686, 1028309, 10785, '<td valign="top">Quite a range in the highlights and shadows, so you did well to expose the objects. A little too much contrast kind of forced more shadows into the black, but then again, there aren''t too many blown highlights.</td>', 'Quite a range in the highlights and shadows, so you did well to expose the objects. A little too much contrast kind of forced more shadows into the black, but then again, there aren''t too many blown highlights.', '2012-08-05 22:23:04.000000', NULL, 1),
(6835689, 1027420, 10785, '<td valign="top">Great stop motion capture. I have to ask, is that square blue thing on the right a... uh, nevermind.</td>', 'Great stop motion capture. I have to ask, is that square blue thing on the right a... uh, nevermind.', '2012-08-05 22:25:39.000000', NULL, 1),
(6835691, 1028336, 10785, '<td valign="top">So cute. Perhaps using a 3/4 ratio crop could have removed some of the unnecessary space at the top?</td>', 'So cute. Perhaps using a 3/4 ratio crop could have removed some of the unnecessary space at the top?', '2012-08-05 22:27:16.000000', NULL, 1),
(6835693, 1026778, 10785, '<td valign="top">I think a lot of excess processing went into this image with additional background blur and some heavy contrast and color saturation being added. I don''t think it needed so much.</td>', 'I think a lot of excess processing went into this image with additional background blur and some heavy contrast and color saturation being added. I don''t think it needed so much.', '2012-08-05 22:31:55.000000', NULL, 1),
(6835703, 1024832, 151157, '<td valign="top">What an awesome shot. So sharp.</td>', 'What an awesome shot. So sharp.', '2012-08-05 22:56:06.000000', NULL, 1),
